import { MeshPhysicalNodeMaterial, BoxGeometry, Mesh, Group, DirectionalLight } from 'three/webgpu';
import { uv, mix, color as tslColor } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group: GroupClass, Mesh: MeshClass, BoxGeometry: BoxGeo, DirectionalLight: DirLight } = THREE;

  const root = new GroupClass();
  const timelines = [];
  const materials = [];
  const geometries = [];

  const colors = config.intent?.visualSpec?.colors || { paper: '#e8ecf2' };

  // Kicker "AS FEATURED IN"
  const kickerText = ctx.fontAtlas.createText('AS FEATURED IN', {
    fontSize: 9,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1.2,
  });

  // Grid dimensions: 3x2 tiles, 1.0w x 0.62h each, 0.25 gap
  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;
  const cols = 3;
  const rows = 2;
  const gridH = rows * tileH + (rows - 1) * gap; // 1.49

  // Position kicker 0.3 units above grid
  kickerText.position.y = gridH / 2 + 0.3;
  root.add(kickerText);

  // Brand marks for 6 tiles
  const brandMarks = ['HODINKEE', 'MONOCLE', 'WALLPAPER', 'ESQUIRE', 'WIRED', 'FINANCIAL TIMES'];
  const tiles = [];

  // Create 3x2 grid of tiles
  let tileIdx = 0;
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const tileGroup = new GroupClass();

      // Tile background geometry
      const geo = new BoxGeo(tileW, tileH, 0.01);
      geometries.push(geo);

      // Brushed-metal PBR material with vertical gradient
      const mat = new MeshPhysicalNodeMaterial({
        metalness: 0.5,
        roughness: 0.55,
        clearcoat: 0.2,
        anisotropy: 0.6,
        transparent: true,
        opacity: 1.0,
      });

      // Vertical gradient from #1a1a22 (top) to #121218 (bottom)
      const uvNode = uv();
      const topColor = tslColor(0x1a1a22);
      const botColor = tslColor(0x121218);
      mat.colorNode = mix(topColor, botColor, uvNode.y);

      materials.push(mat);

      const tileMesh = new MeshClass(geo, mat);
      tileGroup.add(tileMesh);

      // Brand wordmark text, monochrome, 78% opacity
      const textMesh = ctx.fontAtlas.createText(brandMarks[tileIdx], {
        fontSize: 13,
        color: colors.paper,
        align: 'center',
      });
      textMesh.position.z = 0.01;
      setMaterialOpacity(textMesh, 0.78);
      tileGroup.add(textMesh);

      // Position in grid, centered
      const x = (col - (cols - 1) / 2) * (tileW + gap);
      const y = ((rows - 1) / 2 - row) * (tileH + gap);
      tileGroup.position.set(x, y, 0);

      tileGroup.userData = {
        originalPos: { x, y, z: 0 },
        textMesh,
        mat,
      };

      // Hover handlers: opacity 0.78→1.0, z 0→0.05, 160ms
      tileGroup.userData.handlers = {
        pointerenter: () => {
          const tl = gsap.timeline();
          tl.to(tileGroup.position, { z: 0.05, duration: 0.16, ease: [0.25, 0.46, 0.45, 0.94] }, 0);
          tl.to(mat, { opacity: 1.0, duration: 0.16, ease: [0.25, 0.46, 0.45, 0.94] }, 0);
          animateMaterials(textMesh, { opacity: 1.0 }, 0.16, 0, tl);
          timelines.push(tl);
        },
        pointerleave: () => {
          const tl = gsap.timeline();
          tl.to(tileGroup.position, { z: 0, duration: 0.16, ease: [0.25, 0.46, 0.45, 0.94] }, 0);
          tl.to(mat, { opacity: 0.78, duration: 0.16, ease: [0.25, 0.46, 0.45, 0.94] }, 0);
          animateMaterials(textMesh, { opacity: 0.78 }, 0.16, 0, tl);
          timelines.push(tl);
        },
      };

      root.add(tileGroup);
      tiles.push(tileGroup);
      tileIdx++;
    }
  }

  // Entrance animation: fade-up (opacity 0→1, y +0.2→0) with 80ms stagger
  const entranceTl = gsap.timeline();
  tiles.forEach((tile, idx) => {
    // Initial state: pushed down and invisible
    tile.position.y += 0.2;
    tile.userData.mat.opacity = 0;
    setMaterialOpacity(tile.userData.textMesh, 0);

    const delay = idx * 0.08;

    // Animate position
    entranceTl.to(
      tile.position,
      { y: tile.userData.originalPos.y, duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] },
      delay
    );

    // Animate tile opacity
    entranceTl.to(
      tile.userData.mat,
      { opacity: 0.78, duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] },
      delay
    );

    // Animate text opacity
    animateMaterials(tile.userData.textMesh, { opacity: 0.78 }, 0.5, delay, entranceTl);
  });
  timelines.push(entranceTl);

  // Key light at 35° elevation to rake across brushed metal tiles
  const keyLight = new DirLight(0xffffff, 1.2);
  const angle = Math.PI * 35 / 180;
  keyLight.position.set(Math.cos(angle), Math.sin(angle), 1.5);
  keyLight.target.position.set(0, 0, 0);
  root.add(keyLight);
  root.add(keyLight.target);

  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    materials.forEach(m => m.dispose());
    geometries.forEach(g => g.dispose());
  };

  return root;
}

function setMaterialOpacity(object, opacity) {
  const traverse = (node) => {
    if (node.material) {
      const matArray = Array.isArray(node.material) ? node.material : [node.material];
      matArray.forEach(m => {
        m.transparent = true;
        m.opacity = opacity;
      });
    }
    node.children?.forEach(traverse);
  };
  traverse(object);
}

function animateMaterials(object, props, duration, delay, timeline) {
  const traverse = (node) => {
    if (node.material) {
      const matArray = Array.isArray(node.material) ? node.material : [node.material];
      matArray.forEach(m => {
        if (props.opacity !== undefined) m.transparent = true;
        timeline.to(m, { ...props, duration, ease: [0.25, 0.46, 0.45, 0.94] }, delay);
      });
    }
    node.children?.forEach(traverse);
  };
  traverse(object);
}
